def refs():
    return [{**s, "subject": "science", "locator": "呼吸道順序、呼吸運動、肺泡氣體交換、氧氣與二氧化碳、呼吸作用與呼吸運動區分、呼出氣體證據", "observedPattern": "公立學校公開生物科試題常以橫膈位置、呼吸道路徑、呼出氣體檢測、肺泡與微血管資料及呼吸作用概念比較，要求由構造、氣體濃度與壓力變化推論；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


