Q = [
    make(1, "下列哪一條是空氣由外界進入肺部時的合理路徑？", {"A": "鼻腔→咽→喉→氣管→支氣管→肺泡", "B": "鼻腔→肺泡→咽→氣管→胃", "C": "肺泡→支氣管→氣管→咽→鼻腔", "D": "口腔→食道→胃→肺泡→血液"}, "吸氣時空氣依序通過鼻腔、咽、喉、氣管與支氣管，最後到達肺泡；食道與胃屬消化系統，不是空氣通道。", "流程題先固定空氣的入口與交換終點，再檢查中間構造是否屬呼吸道。", ["找出空氣進入人體的入口鼻腔。", "依呼吸道連續結構排列咽、喉、氣管與支氣管。", "把肺泡放在氣道末端作為氣體交換處。", "排除逆向路徑與消化道器官。", "所以選 A。"], "easy"),
    make(2, "吸氣時，哪一組身體變化最符合胸腔擴大的情況？", {"A": "橫膈收縮下降、肋骨上升，胸腔體積增加，空氣進入肺", "B": "橫膈放鬆上升、肋骨下降，胸腔體積增加，空氣進入肺", "C": "橫膈收縮上升、肋骨下降，胸腔體積減少，空氣進入肺", "D": "橫膈放鬆下降、肋骨上升，胸腔體積減少，空氣進入肺"}, "吸氣時橫膈收縮而下降、肋骨上提，使胸腔體積增大、壓力降低，空氣因而流入肺部。", "用『肌肉動作→胸腔體積→壓力差→氣流方向』四步連鎖判斷。", ["先判定吸氣需要空氣流入肺。", "確認要讓空氣流入，胸腔體積必須增加。", "連結胸腔擴大到橫膈下降與肋骨上升。", "檢查是否同時符合壓力降低與氣流進入。", "所以選 A。"], "medium"),
    make(3, "肺泡適合進行氣體交換的主要原因為何？", {"A": "肺泡數量多、表面積大，壁薄且外圍有豐富微血管", "B": "肺泡壁厚且沒有血管，可防止氣體進入血液", "C": "肺泡內有胃酸，可以把氧氣製造成二氧化碳", "D": "肺泡會主動把所有氣體泵到食道"}, "肺泡提供大的交換表面，薄壁縮短擴散距離，周圍微血管則可接收氧並帶走二氧化碳，三者共同提升交換效率。", "結構功能題把表面積、距離與運輸三個條件逐一對照。", ["找出氣體交換需要接觸面積與短距離。", "確認肺泡數量多可增加總表面積。", "確認薄壁有利於氣體擴散。", "補上外圍微血管負責承接與帶走氣體。", "所以選 A。"], "easy"),
    make(4, "肺泡與周圍微血管進行氣體交換時，氧氣的主要移動方向為何？", {"A": "由肺泡空氣擴散進入微血管血液", "B": "由微血管血液擴散進入肺泡的氧氣", "C": "由胃部經食道泵入肺泡", "D": "由肺泡直接流入淋巴而不經血液"}, "吸入空氣到達肺泡後，肺泡內氧氣濃度通常高於缺氧血，氧氣沿濃度差擴散進入微血管血液；二氧化碳方向則相反。", "氣體擴散題先比較交換兩側的濃度或分壓，再決定箭頭方向。", ["先確認交換兩側是肺泡空氣與微血管血液。", "判斷肺泡內氧氣相對較多。", "把氧氣箭頭畫向血液。", "排除胃、淋巴與逆向箭頭等不符合構造的路徑。", "所以選 A。"], "medium"),
    make(5, "下列哪項證據最能支持『呼出的氣體含有較多二氧化碳』？", {"A": "把呼出氣體通入澄清石灰水，石灰水變混濁", "B": "把呼出氣體吹向乾燥藍色氯化亞鈷試紙，試紙保持藍色", "C": "看到呼氣時胸腔變小，就能直接測出二氧化碳含量", "D": "吸入空氣無色，所以呼出氣體一定沒有二氧化碳"}, "二氧化碳可使澄清石灰水產生混濁現象，這是較直接的檢測證據；氯化亞鈷試紙主要檢測水分，不能代替二氧化碳檢測。", "證據題要先確認檢測工具對應的物質，不因同樣是呼氣就混用試劑。", ["先辨認題目要證明的是二氧化碳。", "找出能與二氧化碳產生明顯反應的石灰水。", "把石灰水混濁連到二氧化碳存在。", "排除只能測水分或只靠外觀推測的選項。", "所以選 A。"], "medium"),
    make(6, "『呼吸作用』與『呼吸運動』的區別，哪項正確？", {"A": "呼吸作用在細胞中釋放養分能量；呼吸運動是胸腔與肺的進出氣體動作", "B": "呼吸作用只發生在肺泡；呼吸運動在粒線體內完成", "C": "兩者都只是空氣由鼻腔進入肺的同一件事", "D": "呼吸作用不需要養分，呼吸運動會製造氧氣"}, "呼吸作用是細胞利用養分與氧進行代謝並釋放能量的化學過程；呼吸運動則是吸氣與呼氣的機械過程，兩者相關但不相同。", "名詞辨析題先確認一個詞描述的是細胞代謝，還是器官的氣流運動。", ["圈出呼吸作用與呼吸運動兩個名詞。", "把呼吸作用定位到細胞代謝與能量釋放。", "把呼吸運動定位到胸腔體積與氣流進出。", "排除肺泡製能、粒線體進氣與製造氧氣的說法。", "所以選 A。"], "easy"),
    make(7, "跑步時呼吸頻率與深度增加，最合理的生理解釋為何？", {"A": "肌肉需氧與產生二氧化碳增加，身體加強通氣以配合氣體交換與排出", "B": "跑步使細胞停止呼吸作用，因此需要把氧氣留在肺內", "C": "呼吸變快是為了在肺泡製造更多葡萄糖", "D": "只要呼吸變快，就代表血液不再運輸二氧化碳"}, "運動時細胞代謝需求提高，需取得更多氧並排出較多二氧化碳；增加通氣可提高肺泡與外界的氣體交換，不代表肺泡製造葡萄糖。", "情境題先找活動量改變的細胞需求，再把需求連到呼吸運動的調整。", ["辨認跑步會提高肌肉細胞代謝。", "列出代謝增加造成的氧需求與二氧化碳產生。", "連結呼吸頻率與深度增加到通氣加強。", "排除停止呼吸、肺泡製糖與停止運輸等敘述。", "所以選 A。"], "medium"),
    make(8, "呼氣時，哪個描述最合理？", {"A": "胸腔體積減小、肺內壓力相對升高，空氣由肺泡流向外界", "B": "胸腔體積增大、肺內壓力降低，空氣由外界流入肺", "C": "橫膈收縮下降，肺內壓力降低，空氣流出肺", "D": "肺泡把二氧化碳轉成氧氣後，氧氣才流出鼻腔"}, "呼氣時胸腔體積減小，使肺內壓力相對升高，空氣由肺部流向外界；氣體成分不會在肺泡中被直接轉換成另一種氣體。", "用壓力差判斷氣流，並把呼氣的機械事件和肺泡交換的化學組成分開。", ["先確認題目問的是空氣離開肺的方向。", "判斷肺部體積減少會使壓力上升。", "將氣流箭頭畫向外界。", "排除吸氣條件與肺泡製造氧氣的錯誤因果。", "所以選 A。"], "medium"),
    make(9, "若某人吸入含氧量較低的空氣，仍能判斷肺泡氣體交換的基本方向嗎？", {"A": "可以；仍應依肺泡與血液兩側的氧、二氧化碳濃度差判斷，方向可能因差值改變", "B": "不可以；只要含氧量降低，肺泡就完全停止所有氣體交換", "C": "可以；氧氣永遠由血液流入肺泡，與濃度無關", "D": "不可以；肺泡只交換水蒸氣，不交換氧與二氧化碳"}, "氣體交換依兩側濃度或分壓差進行；吸入空氣改變可能使交換效率或某些方向條件改變，但不能說肺泡完全不交換氣體。", "推理題不要只背固定箭頭，要把方向建立在濃度差與兩側物質上。", ["列出肺泡與血液各自包含的氧氣與二氧化碳。", "確認擴散方向取決於兩側濃度或分壓差。", "再考慮低氧空氣可能降低交換效率。", "排除與濃度無關、完全停止或只交換水的說法。", "所以選 A。"], "hard"),
    make(10, "要用實驗模型比較不同呼吸狀態的氣體交換，哪項設計最能保留可判讀證據？", {"A": "固定測量時間與氣體體積，分別收集吸入與呼出氣體，再用相同檢測方法比較氧氣、二氧化碳或水分指標", "B": "只讓受試者描述感覺，不記錄氣體或時間", "C": "不同組使用不同試劑與不同體積，最後只比較顏色深淺", "D": "看到胸腔起伏就直接宣布所有氣體濃度相同"}, "要比較呼吸狀態，需控制收集量、時間與檢測方法，並將吸入與呼出氣體的可觀察指標並列；只靠感覺或未控制的顏色無法支持結論。", "探究題採『控制條件—同一測量—比較資料—限制結論』順序。", ["先指定要比較的呼吸狀態與氣體樣本。", "固定收集時間、體積與檢測方法。", "記錄吸入與呼出樣本的可觀察變化。", "用成對資料比較，不把胸腔外觀直接當成濃度測量。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
